cat > fake-runner.mjs <<'EOF'
// A ten-line imitation of what a runner does with a run: step:
// it pastes the event's text into the script, then hands the result to bash.
import { readFileSync } from "node:fs";
import { execFileSync } from "node:child_process";

const [file, message] = process.argv.slice(2);
const expr = "${{ github.event.workflow_run.head_commit.message }}";
const script = readFileSync(file, "utf8").replaceAll(expr, () => message);
console.log(`--- the script bash receives:\n${script}--- output:`);
execFileSync("bash", ["-e", "-c", script], { stdio: "inherit", env: { ...process.env, MESSAGE: message } });
EOF
